import{j as t}from"./blog-pages-BaE92hYU.js";import{P as a}from"./compare-pages-BwwJjgUS.js";const o=[{factor:"Connection method",atlantis:"REST via SAP Gateway / OData",competitor:"BAPI/IDoc via SAP PI/PO; SOAP via SAP NetWeaver"},{factor:"Supported SAP versions",atlantis:"SAP S/4HANA Cloud, S/4HANA on-prem, ECC 6.0",competitor:"Same — connector code paths for each"},{factor:"Authentication",atlantis:"OAuth2 client credentials, X.509 mTLS, basic auth",competitor:"SAP standard service user with role-based authorization"},{factor:"Sync direction (equipment master)",atlantis:"Bi-directional, SAP master of record",competitor:"—"},{factor:"Sync direction (work orders)",atlantis:"Atlantis raises Notification, SAP creates Work Order, status flows back",competitor:"—"},{factor:"Sync direction (cost actuals)",atlantis:"SAP → Atlantis on confirmation",competitor:"—"},{factor:"Deployment time",atlantis:"4–6 weeks typical; 8 weeks for complex landscapes",competitor:"—"},{factor:"SAP-side prerequisites",atlantis:"SAP Gateway active, OAuth2 configured, service user with PM_NOTIFICATION + PM_ORDER + EQUIPMENT_MASTER auths",competitor:"—"},{factor:"Certified status",atlantis:"Engineered against SAP Plant Maintenance standard objects per SAP Help documentation",competitor:"—"}],i=[{question:"Does Atlantis use BAPI/IDoc or REST for SAP integration?",answer:"Both, depending on your SAP landscape and preference. The default and recommended path is REST via SAP Gateway / OData — it&rsquo;s lighter, faster to deploy, easier to debug, and supported across S/4HANA and ECC 6.0. For customers with established PI/PO middleware investments, we also support BAPI/IDoc via the standard PI/PO adapters. The data model is the same; only the transport differs."},{question:"Which SAP PM objects do you sync?",answer:"Equipment master (EQUI), Functional Location (FL), Notification (PM Notification — typically type M2 or M3), Maintenance Order (Work Order), Maintenance Plan, Job Plan, Cost Center, and Customer/Supplier where relevant. Inspection findings flow Atlantis → SAP as Notifications which then route into the standard Maintenance Order workflow. We do not directly create Maintenance Orders from Atlantis — that breaks the SAP planning workflow. The Notification path is correct and what SAP customers expect."},{question:"How do FFS/RBI results flow into SAP?",answer:"API 579 FFS results and API 581 RBI risk band changes flow into SAP as Notifications with structured long-text containing the calculation summary and a link back to the full Atlantis record. Risk-band escalations (e.g. Medium → High) trigger automatic Notification creation; risk de-escalations are logged but typically not auto-created as Notifications. Risk-driven inspection interval changes flow into the SAP Maintenance Plan to update the next due date."},{question:"What about SAP authorizations?",answer:"We work with your SAP Basis team to define a service user with the minimum authorizations required: read on EQUI / FL / Maintenance Plan, write on Notification, read on Maintenance Order. We do not require dialog-user privileges and do not require SAP_ALL or any broad authorizations. The full authorization matrix is documented in the integration specification and reviewed during scoping."},{question:"Can this work with SAP S/4HANA Cloud?",answer:"Yes. S/4HANA Cloud uses the same OData services as on-prem S/4HANA but with cloud authentication patterns (typically OAuth2 client credentials via SAP Cloud Identity). Implementation is generally faster (4 weeks typical) because there&rsquo;s no Basis side custom transport request management. We have customers running this in production."}];function c(){const n={"@context":"https://schema.org","@graph":[{"@type":"SoftwareApplication",name:"Atlantis Digital Twin — SAP PM Integration",applicationCategory:"BusinessApplication",operatingSystem:"Web",description:"Native SAP PM integration for Atlantis Digital Twin — REST via SAP Gateway, supports S/4HANA Cloud, S/4HANA on-prem, ECC 6.0. Bi-directional equipment master sync, inspection findings → Notifications → Work Orders, cost actuals back to Atlantis.",offers:{"@type":"Offer",price:"0",priceCurrency:"USD"},provider:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"Article",headline:"Atlantis Digital Twin — SAP PM Integration Architecture & Deployment [2026]",datePublished:"2026-05-09",dateModified:"2026-05-09",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"FAQPage",mainEntity:i.map(e=>({"@type":"Question",name:e.question,acceptedAnswer:{"@type":"Answer",text:e.answer}}))}]};return t.jsx(a,{title:"Atlantis Digital Twin — SAP PM Integration: REST, BAPI, S/4HANA, ECC [2026]",description:"SAP PM integration for Atlantis Digital Twin: REST via SAP Gateway, BAPI/IDoc via PI/PO. Bi-directional equipment master, inspection findings → Notifications → Work Orders. 4-6 wk deploy.",canonical:"https://atlantisndt.com/integrations/sap-pm",eyebrow:"Integration",h1:"Atlantis Digital Twin — SAP PM Integration: REST, BAPI/IDoc, S/4HANA & ECC [2026]",intro:"Bi-directional REST integration to SAP Plant Maintenance. Equipment master flows SAP → Atlantis; inspection findings, FFS/RBI results, and recommended work flow Atlantis → SAP as Notifications which route to Work Orders. 4–6 weeks to production.",heroGradient:"from-blue-700 to-sky-800",competitorLabel:"Notes",compareRows:o,faqs:i,related:[{href:"/integrations/ibm-maximo",title:"IBM Maximo Integration",blurb:"EAM-class integration alternative for non-SAP shops."},{href:"/integrations/oracle-erp-cloud",title:"Oracle ERP Cloud Integration",blurb:"REST via Oracle Integration Cloud."},{href:"/integrations/meridium-apm",title:"Meridium APM Integration",blurb:"RBI library import + bidirectional sync."},{href:"/digital-twins",title:"Atlantis Digital Twin",blurb:"Product page — features, pricing, case studies."},{href:"/erp",title:"Atlantis NDT ERP",blurb:"Companion ERP — jobs, certs, equipment, invoicing."},{href:"/contact",title:"Book a Scoping Call",blurb:"60-minute call with a Level III consultant + integration architect."}],ctaTitle:"Plug Atlantis Into Your SAP Landscape",ctaSubtitle:"Bring your SAP PM org and a sample equipment master export. We’ll show the integration in 30 minutes.",structuredData:n,bodyChildren:t.jsxs(t.Fragment,{children:[t.jsx("h2",{children:"Architecture overview"}),t.jsx("p",{children:"Atlantis Digital Twin connects to SAP Plant Maintenance via REST over SAP Gateway / OData (default) or via BAPI/IDoc through SAP PI/PO (when customer landscape standards require). Both transport options expose the same logical data model. Authentication is OAuth2 client credentials (recommended) or X.509 mTLS for high-security environments. A dedicated SAP service user is created with minimum authorizations: read on EQUI / Functional Location / Maintenance Plan, write on Notification, read on Maintenance Order."}),t.jsx("h2",{children:"Data flow"}),t.jsx("p",{children:"Equipment master and Functional Location hierarchy flow SAP → Atlantis on a scheduled sync (default: every 4 hours, configurable). SAP is the system of record. Atlantis attaches its inspection-domain extensions (CMLs, weld registers, PAUT scan archive, FFS results, RBI band) to the equipment record in its own data model — SAP is not modified or extended."}),t.jsx("p",{children:"Inspection findings, FFS results, and RBI risk-band changes flow Atlantis → SAP as Notifications (typically PM Notification type M2 for ‘malfunction observation’ or M3 for ‘maintenance request’). The Notification long-text contains a structured summary of the finding and a deep link back to the full Atlantis record. Notifications then route into the standard SAP Maintenance Order workflow — Atlantis does not create Maintenance Orders directly because that breaks the SAP planning workflow."}),t.jsx("p",{children:"Cost actuals and Maintenance Order completion data flow SAP → Atlantis on Notification close-out. This closes the loop in Atlantis (the integrity engineer sees that the recommended work was done, on what date, at what cost) and feeds the integrity-program KPI dashboards."}),t.jsx("h2",{children:"Deployment timeline"}),t.jsxs("ul",{children:[t.jsxs("li",{children:[t.jsx("strong",{children:"Week 1–2:"})," SAP Basis kickoff, service user provisioning, OAuth2 setup, sandbox connection test, equipment master schema review."]}),t.jsxs("li",{children:[t.jsx("strong",{children:"Week 3–4:"})," Initial equipment master import, asset hierarchy validation, Notification create test in sandbox, integrity team walkthrough."]}),t.jsxs("li",{children:[t.jsx("strong",{children:"Week 5–6:"})," User acceptance testing, production cut-over, monitoring dashboards live."]})]}),t.jsx("p",{children:"Complex landscapes (multiple SAP systems, federated equipment master, custom Z-fields critical to the integrity workflow) extend to 8 weeks. S/4HANA Cloud deployments are typically faster (4 weeks) because there’s no Basis-side custom transport management."}),t.jsx("h2",{children:"What about SAP S/4HANA Cloud vs on-prem?"}),t.jsx("p",{children:"Same logical integration, different authentication. S/4HANA Cloud uses OAuth2 client credentials via SAP Cloud Identity. On-prem S/4HANA and ECC 6.0 use SAP Gateway with the same OAuth2 path or basic auth in lower environments. The functional integration is identical from Atlantis’ perspective."}),t.jsx("h2",{children:"Authorization model"}),t.jsx("p",{children:"We work with your SAP Basis and security team to define a minimum-authorization service user. We do not require SAP_ALL, dialog-user privileges, or broad cross-module authorizations. The standard role bundle is: PM_NOTIFICATION (write), PM_ORDER (read), EQUIPMENT_MASTER (read), FUNCTIONAL_LOCATION (read), MAINTENANCE_PLAN (read). Specific authorization objects (BEGRU, IWERK, etc.) are scoped to the plants and work centers in your integrity program. The full authorization matrix is documented in the integration specification and reviewed during scoping."}),t.jsx("h2",{children:"Beyond Plant Maintenance — connected SAP modules"}),t.jsx("p",{children:"The same integration patterns extend to adjacent SAP modules when needed: SAP Asset Management (EAM), SAP Predictive Maintenance & Service, SAP Asset Intelligence Network, SAP Document Management Service for inspection report archiving. We work to your landscape — the goal is to fit Atlantis into the existing SAP architecture rather than impose a parallel system."})]})})}export{c as default};
